-- Fake Module Scripts:

local fake_module_scripts = {}


-- Fake Local Scripts:

local function ISVJ_fake_script() -- Fake Script: StarterGui.AuroraGui_Backup.AuroraAnimator
    local script = Instance.new("LocalScript")
    script.Name = "AuroraAnimator"
    script.Parent = Converted["_AuroraGui_Backup"]
    local req = require
    local require = function(obj)
        local fake = fake_module_scripts[obj]
        if fake then
            return fake()
        end
        return req(obj)
    end

	local RunService = game:GetService("RunService")
	local TweenService = game:GetService("TweenService")
	
	local frame = script.Parent:WaitForChild("AuroraFrame")
	local aurora = frame:WaitForChild("Aurora")
	local starsFolder = frame:WaitForChild("Stars")
	
	local TAU = math.pi * 2
	local N = 64
	
	local palette = {
		Color3.fromRGB(70, 255, 140), Color3.fromRGB(60, 235, 200), Color3.fromRGB(70, 170, 255),
		Color3.fromRGB(150, 100, 255), Color3.fromRGB(240, 80, 220), Color3.fromRGB(110, 150, 255),
		Color3.fromRGB(60, 240, 170),
	}
	local function pal(u)
		u = u % 1
		local n = #palette
		local p = u * n
		local i = math.floor(p)
		return palette[i % n + 1]:Lerp(palette[(i + 1) % n + 1], p - i)
	end
	
	local configs = {
		{name="Layer1", base=0.50, a1=0.10, f1=1.1, s1=0.35, a2=0.04, f2=2.3, s2=0.6,  h=0.26, hv=0.08, alpha=0.25, off=0.00, drift=0.012},
		{name="Layer2", base=0.46, a1=0.09, f1=1.4, s1=-0.28,a2=0.05, f2=2.9, s2=0.45, h=0.22, hv=0.07, alpha=0.30, off=0.30, drift=0.018},
		{name="Layer3", base=0.40, a1=0.12, f1=0.8, s1=0.22, a2=0.03, f2=3.4, s2=0.8,  h=0.30, hv=0.12, alpha=0.35, off=0.55, drift=0.010},
		{name="Layer4", base=0.52, a1=0.07, f1=1.9, s1=0.5,  a2=0.03, f2=3.0, s2=-0.7, h=0.14, hv=0.04, alpha=0.20, off=0.80, drift=0.022},
	}
	
	local layers = {}
	for _, cfg in ipairs(configs) do
		local layer = aurora:WaitForChild(cfg.name)
		local strips = {}
		for i = 1, N do strips[i] = layer:WaitForChild("S" .. i) end
		table.insert(layers, {cfg = cfg, strips = strips})
	end
	
	local stars = starsFolder:GetChildren()
	local W = 1 / N + 0.004
	local frameCount = 0
	
	RunService.RenderStepped:Connect(function()
		local t = os.clock()
		frameCount += 1
	
		for _, L in ipairs(layers) do
			local cfg, strips = L.cfg, L.strips
			for i = 1, N do
				local x = (i - 0.5) / N
				local cy = cfg.base
					+ cfg.a1 * math.sin(x * TAU * cfg.f1 + t * cfg.s1 * 2)
					+ cfg.a2 * math.sin(x * TAU * cfg.f2 - t * cfg.s2 * 2)
				local hh = (cfg.h + cfg.hv * math.sin(x * TAU * 1.3 + t * 0.5 + cfg.off * 6))
					* (1 + 0.12 * math.sin(x * TAU * 9 + t * 1.6 + cfg.off * 5))
				local s = strips[i]
				s.Position = UDim2.fromScale(x, cy)
				s.Size = UDim2.fromScale(W, hh)
				s.BackgroundColor3 = pal(x * 0.8 + t * cfg.drift + cfg.off)
				s.BackgroundTransparency = math.clamp(cfg.alpha + 0.15 * math.sin(i * 0.35 + t * 1.1 + cfg.off * 7), 0, 0.9)
			end
		end
	
		if frameCount % 3 == 0 then
			for i, s in ipairs(stars) do
				local base = s:GetAttribute("Base") or 0.3
				s.BackgroundTransparency = math.clamp(base + 0.35 * (0.5 + 0.5 * math.sin(t * (0.8 + (i % 5) * 0.3) + i)), 0, 0.95)
			end
		end
	end)
	
	-- Shooting star
	local shoot = Instance.new("Frame")
	shoot.Name = "ShootingStar"
	shoot.AnchorPoint = Vector2.new(0.5, 0.5)
	shoot.Size = UDim2.fromOffset(80, 2)
	shoot.Rotation = 22
	shoot.BackgroundColor3 = Color3.new(1, 1, 1)
	shoot.BackgroundTransparency = 1
	shoot.BorderSizePixel = 0
	shoot.ZIndex = 2
	shoot.Parent = frame
	local g = Instance.new("UIGradient")
	g.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0)})
	g.Parent = shoot
	
	task.spawn(function()
		local rng = Random.new()
		while shoot.Parent do
			task.wait(rng:NextNumber(5, 12))
			local sx, sy = rng:NextNumber(0.1, 0.55), rng:NextNumber(0.04, 0.22)
			shoot.Position = UDim2.fromScale(sx, sy)
			shoot.BackgroundTransparency = 0
			local info = TweenInfo.new(0.9, Enum.EasingStyle.Linear)
			TweenService:Create(shoot, info, {Position = UDim2.fromScale(sx + 0.25, sy + 0.12), BackgroundTransparency = 1}):Play()
		end
	end)
	
end

coroutine.wrap(ISVJ_fake_script)()-- Please leave these comments in and leave credit, it took me a while to make this
